const MODE = '{{mode}}', N = {{n}};
const load = [0, 0, 0, 0];
for (let i = 0; i < N; i++) {
  const cost = 1 + Math.floor(Math.random() * 4);   // 요청마다 무게가 다르다
  let k = 0;
  if (MODE === 'rr') k = i % 4;
  else if (MODE === 'rand') k = Math.floor(Math.random() * 4);
  else k = load.indexOf(Math.min(...load));
  load[k] += cost;
}
ctx.clearRect(0, 0, W(), H());
const max = Math.max(...load);
load.forEach((v, k) => {
  const h = (v / max) * (H() - 80);
  ctx.fillStyle = v === max ? '#f87171' : '#60a5fa';
  ctx.fillRect(30 + k * 90, H() - 34 - h, 60, h);
  ctx.fillStyle = '#eee'; ctx.font = '12px system-ui';
  ctx.fillText('서버 ' + (k + 1) + ': ' + v, 30 + k * 90, H() - 14);
});
ctx.fillStyle = '#9ca3af'; ctx.font = '13px system-ui';
ctx.fillText('가장 무거운 곳 ' + max + ' · 가장 가벼운 곳 ' + Math.min(...load) + ' — 차이가 곧 위험', 16, 24);

